<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Discount extends Model { protected $fillable=['code','type','value','minimum_order','starts_at','expires_at','is_active']; protected $casts=['starts_at'=>'datetime','expires_at'=>'datetime','is_active'=>'boolean','value'=>'decimal:2','minimum_order'=>'decimal:2']; public function validFor(float $subtotal):bool{return $this->is_active && $subtotal >= $this->minimum_order && (!$this->starts_at||$this->starts_at->isPast()) && (!$this->expires_at||$this->expires_at->isFuture());} }
